pragma solidity ^0.8.27;

import {Test} from "forge-std/Test.sol";
import {IPool} from "@aave/core-v3/contracts/interfaces/IPool.sol";
import {IPoolAddressesProvider} from "@aave/core-v3/contracts/interfaces/IPoolAddressesProvider.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {MyFlashLoanReceiver} from "../src/MyFlashLoanReceiver.sol";

/// @title MyFlashLoanReceiverAttackTest
/// @notice Generated by HARNESS. Every test below is derived from a documented
/// @notice incident, cited in the comment above it, and fails when the mitigation
/// @notice it names is removed. These run on a mainnet fork against the real
/// @notice protocol â€” not against a mock.
contract MyFlashLoanReceiverAttackTest is Test {
    IPoolAddressesProvider internal constant PROVIDER =
        IPoolAddressesProvider(0x2f39d218133AFaB8F2B819B1066c7E434Ad94E9e);
    address internal constant ASSET = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    IPool internal POOL;
    address internal ATOKEN;
    uint256 internal ONE;
    uint256 internal AMOUNT;
    MyFlashLoanReceiver internal harness;
    address internal owner;
    address internal router;

    function setUp() public {
        // Pinned to block 25710954 by default so the suite is reproducible: an
        // unpinned fork drifts with mainnet and goes red for reasons unrelated to the
        // code. Set TENDERLY_FORK_BLOCK=0 to test against the latest block instead.
        uint256 forkBlock = vm.envOr("TENDERLY_FORK_BLOCK", uint256(25710954));
        if (forkBlock == 0) {
            vm.createSelectFork(vm.envString("MAINNET_RPC_URL"));
        } else {
            vm.createSelectFork(vm.envString("MAINNET_RPC_URL"), forkBlock);
        }

        POOL = IPool(PROVIDER.getPool());
        ATOKEN = POOL.getReserveData(ASSET).aTokenAddress;
        ONE = 10 ** IERC20Metadata(ASSET).decimals();
        AMOUNT = 1_000 * ONE;
        owner = _fresh("owner");
        router = _fresh("router");
        harness = new MyFlashLoanReceiver(address(PROVIDER), ASSET, owner);
        vm.prank(owner);
        harness.setRouterAllowed(router, true);
    }

    /// @dev A plain account for this suite. Common labels ("alice", "owner") have public keys
    /// @dev and carry EIP-7702 delegation code on mainnet that swallows ETH sent to them, so
    /// @dev the label is prefixed and any code at the address is cleared.
    function _fresh(string memory label) internal returns (address a) {
        a = makeAddr(string(abi.encodePacked("harness/MyFlashLoanReceiver/", label)));
        if (a.code.length != 0) vm.etch(a, "");
    }

    /// @dev A valid, benign FlashParams. Attack tests deviate from this deliberately.
    function _defaultFlashParams() internal view returns (MyFlashLoanReceiver.FlashParams memory) {
        return MyFlashLoanReceiver.FlashParams({
            minAmountOut: 1,
            deadline: type(uint256).max,
            router: router
        });
    }

    function _defaultParams() internal view returns (bytes memory) {
        return abi.encode(_defaultFlashParams());
    }

    /// AAVE-FL-001 â€” Flash-loan callback not gated to Pool + initiator
    /// AAVE-FL-001 â€” anyone may call Pool.flashLoanSimple naming OUR contract as the
    /// receiver. Aave then invokes our callback on their behalf, with their params.
    /// Checking msg.sender == Pool is NOT enough: the Pool really is the caller.
    /// This is the bug that drained DODO MarginTrading and Mimo SuperVault.
    /// @dev Incident: DODO MarginTrading â€” https://github.com/sherlock-audit/2023-01-derby-judging/issues/150
    /// @dev Runnable PoC: https://github.com/sanbir/evm-hack-registry/tree/main/2021-03-dodo_flashloan_exp
    /// @dev Incident: Mimo SuperVault (Code4rena H-02) â€” https://code4rena.com/reports/2022-08-mimo
    function test_RejectsThirdPartyInitiator() public {
        address attacker = _fresh("attacker");

        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSignature("NotSelfInitiated(address)", attacker));
        POOL.flashLoanSimple(address(harness), ASSET, AMOUNT, _defaultParams(), 0);
    }

    /// AAVE-FL-002 â€” Attacker-controlled calldata executed from callback params
    /// AAVE-FL-002 â€” the tutorial pattern decodes `params` into (address target,
    /// bytes data) and calls it, turning finding 001 from a revert into a drain.
    /// Here `params` decodes to a fixed struct with no call target, so hostile bytes
    /// cannot become an external call. Asserted even with both other gates satisfied.
    /// @dev Incident: Mimo SuperVault aggregatorSwap(dexTxData) â€” https://code4rena.com/reports/2022-08-mimo
    function test_RejectsAttackerControlledParams() public {
        // Worst case: the attacker somehow satisfies the caller AND initiator gates.
        vm.prank(address(POOL));
        vm.expectRevert();
        harness.executeOperation(ASSET, AMOUNT, AMOUNT / 2000, address(harness), hex"deadbeef");
    }

    /// AAVE-FL-013 â€” Idle funds held on the flash-loan receiver
    /// AAVE-FL-013 â€” a balance sitting on a receiver is repayment for somebody else's
    /// flash loan. An attacker borrows, does nothing, and lets YOUR balance cover the
    /// premium. The initiator gate is what stops it, so assert the balance survives.
    /// @dev Incident: Aave docs warn explicitly; ESE 92391 â€” https://aave.com/docs/developers/smart-contracts/flash-loans
    function test_IdleFundsCannotRepayAttackerLoan() public {
        uint256 idle = 10 * AMOUNT;
        deal(ASSET, address(harness), idle);
        address attacker = _fresh("attacker");

        vm.prank(attacker);
        vm.expectRevert();
        POOL.flashLoanSimple(address(harness), ASSET, AMOUNT, _defaultParams(), 0);

        assertEq(
            IERC20(ASSET).balanceOf(address(harness)),
            idle,
            "idle funds were consumed repaying someone else's flash loan"
        );
    }

    /// AAVE-SWP-014 â€” Missing minAmountOut on the swap leg
    /// AAVE-SWP-014 â€” a swap leg with no floor on output is a free sandwich. The
    /// contract refuses to proceed rather than trusting the caller to pass one.
    /// @dev Incident: vuln/defi/slippage â€” 120 tagged PoCs in the registry â€” https://github.com/sanbir/evm-hack-registry
    function test_RejectsZeroMinAmountOut() public {
        address router = _fresh("router");
        vm.prank(owner);
        harness.setRouterAllowed(router, true);

        MyFlashLoanReceiver.FlashParams memory p = _defaultFlashParams();
        p.router = router;
        p.minAmountOut = 0;

        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSignature("MissingSlippageBound()"));
        harness.initiateFlashLoan(AMOUNT, p);
    }

    /// AAVE-RISK-010 â€” Supply/borrow cap and pause reverts unhandled
    /// AAVE-RISK-010 â€” caps, freezes and pauses make Aave revert mid-flow, and a
    /// leverage loop that ignores them bricks. Halting must be a clean revert that
    /// leaves no partial state, and must be reversible.
    /// @dev Incident: Sherlock Index #267 â€” https://github.com/sherlock-audit/2023-01-index-judging/issues/267
    function test_PausedInitiationRevertsCleanly() public {
        vm.prank(owner);
        harness.pause();

        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSignature("EnforcedPause()"));
        harness.initiateFlashLoan(AMOUNT, _defaultFlashParams());

        // No bricked state: unpausing restores normal operation.
        vm.prank(owner);
        harness.unpause();
        assertFalse(harness.paused(), "contract stuck paused");
    }

    /// AAVE-VLT-009 â€” No ERC20 escape hatch for airdrops / stuck tokens
    /// AAVE-VLT-009 â€” Merkl rewards, airdrops and dust arrive unannounced. Without a
    /// hatch they are stuck forever; with an ungated one, anyone drains the contract.
    /// Both halves are asserted here.
    /// @dev Incident: Morpho integration checklist â€” https://docs.morpho.org/overview/resources/audits/
    function test_SweepIsGatedAndRecoversStrayTokens() public {
        uint256 stray = AMOUNT / 2;
        deal(ASSET, address(harness), stray);
        address stranger = _fresh("stranger");

        vm.prank(stranger);
        vm.expectRevert();
        harness.sweep(ASSET, stranger);

        vm.prank(owner);
        harness.sweep(ASSET, owner);
        assertEq(IERC20(ASSET).balanceOf(owner), stray, "stray tokens not recoverable");
    }

    /// AAVE-RISK-006 â€” LTV-0 aToken poison dust can freeze withdrawals
    /// AAVE-RISK-006 â€” anyone can push a zero-LTV aToken onto this contract. It must
    /// stay inert: the callback gates keep holding and the dust cannot be leveraged
    /// by whoever sent it.
    /// @dev Incident: StErMi â€” Aave v3 LTV-0 bug bounty â€” https://immunefi.com/bug-bounty/aave/
    function test_SurvivesZeroLtvDust() public {
        address griefer = _fresh("griefer");
        deal(ASSET, griefer, AMOUNT);
        vm.startPrank(griefer);
        IERC20(ASSET).approve(address(POOL), AMOUNT);
        POOL.supply(ASSET, AMOUNT, griefer, 0);
        IERC20(ATOKEN).transfer(address(harness), 1);
        vm.stopPrank();

        // The dust must not become a lever for a third-party flash loan.
        vm.prank(griefer);
        vm.expectRevert();
        POOL.flashLoanSimple(address(harness), ASSET, AMOUNT, _defaultParams(), 0);

        assertEq(
            IERC20(ATOKEN).balanceOf(address(harness)),
            1,
            "zero-LTV dust changed the contract's Aave position"
        );
    }
}

