// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {Test} from "forge-std/Test.sol";
import {IPool} from "@aave/core-v3/contracts/interfaces/IPool.sol";
import {IPoolAddressesProvider} from "@aave/core-v3/contracts/interfaces/IPoolAddressesProvider.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {MyFlashLoanReceiver} from "../src/MyFlashLoanReceiver.sol";

/// @dev Two kinds of caller: the operator initiating loans of random size, and an
/// @dev attacker naming the receiver in Pool.flashLoanSimple. The attacker's calls are
/// @dev expected to revert and are wrapped; the operator's must not.
contract MyFlashLoanReceiverHandler is Test {
    /// @dev A plain account for this suite. Common labels ("alice", "owner") have public keys
    /// @dev and carry EIP-7702 delegation code on mainnet that swallows ETH sent to them, so
    /// @dev the label is prefixed and any code at the address is cleared.
    function _fresh(string memory label) internal returns (address a) {
        a = makeAddr(string(abi.encodePacked("harness/MyFlashLoanReceiver/", label)));
        if (a.code.length != 0) vm.etch(a, "");
    }

    MyFlashLoanReceiver internal receiver;
    IPool internal POOL;
    address internal ASSET;
    address internal owner;
    address internal attacker;
    uint256 internal amountUnit;

    uint256 public ghostPremiumsPaid;
    uint256 public ghostAttacks;

    address internal router;

    constructor(MyFlashLoanReceiver receiver_, IPool pool_, address asset_, address owner_, uint256 amountUnit_, address router_) {
        receiver = receiver_;
        POOL = pool_;
        ASSET = asset_;
        owner = owner_;
        amountUnit = amountUnit_;
        router = router_;
        attacker = _fresh("attacker");
    }

    function _params() internal view returns (bytes memory) {
        return abi.encode(MyFlashLoanReceiver.FlashParams({minAmountOut: 1, deadline: type(uint256).max, router: router}));
    }

    function operatorLoan(uint256 amount) external {
        amount = bound(amount, amountUnit / 10, 200 * amountUnit);
        // Aave rounds the premium half-up (PercentageMath); fund it rounded up.
        uint256 premium = (amount * POOL.FLASHLOAN_PREMIUM_TOTAL() + 9_999) / 10_000;
        // The premium is the one thing a strategy cannot conjure; fund it explicitly.
        deal(ASSET, address(receiver), IERC20(ASSET).balanceOf(address(receiver)) + premium);
        uint256 before = IERC20(ASSET).balanceOf(address(receiver));
        vm.prank(owner);
        receiver.initiateFlashLoan(amount, MyFlashLoanReceiver.FlashParams({minAmountOut: 1, deadline: type(uint256).max, router: router}));
        uint256 after_ = IERC20(ASSET).balanceOf(address(receiver));
        require(before - after_ <= premium, "loan cost more than the premium");
        ghostPremiumsPaid += premium;
    }

    function attackerLoan(uint256 amount) external {
        amount = bound(amount, 1, 200 * amountUnit);
        vm.prank(attacker);
        try POOL.flashLoanSimple(address(receiver), ASSET, amount, _params(), 0) {
            revert("a third party drove the callback");
        } catch {
            ghostAttacks++;
        }
    }
}

/// @title MyFlashLoanReceiverPropertiesTest
/// @notice Generated by HARNESS. Properties that hold for this contract and must
/// @notice keep holding for anything you build on it. Foundry fuzzes the inputs
/// @notice and the action sequences; the values are not hand-picked. Runs on a
/// @notice mainnet fork against the real protocol.
contract MyFlashLoanReceiverPropertiesTest is Test {
    IPoolAddressesProvider internal constant PROVIDER =
        IPoolAddressesProvider(0x2f39d218133AFaB8F2B819B1066c7E434Ad94E9e);
    address internal constant ASSET = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    IPool internal POOL;
    address internal ATOKEN;
    uint256 internal ONE;
    uint256 internal AMOUNT;
    MyFlashLoanReceiver internal harness;
    address internal owner;
    address internal router;
    MyFlashLoanReceiverHandler internal handler;
    address internal DEBT_TOKEN;

    function setUp() public {
        // Pinned to block 25710954 by default so the suite is reproducible: an
        // unpinned fork drifts with mainnet and goes red for reasons unrelated to the
        // code. Set TENDERLY_FORK_BLOCK=0 to test against the latest block instead.
        uint256 forkBlock = vm.envOr("TENDERLY_FORK_BLOCK", uint256(25710954));
        if (forkBlock == 0) {
            vm.createSelectFork(vm.envString("MAINNET_RPC_URL"));
        } else {
            vm.createSelectFork(vm.envString("MAINNET_RPC_URL"), forkBlock);
        }

        POOL = IPool(PROVIDER.getPool());
        ATOKEN = POOL.getReserveData(ASSET).aTokenAddress;
        ONE = 10 ** IERC20Metadata(ASSET).decimals();
        AMOUNT = 1_000 * ONE;
        owner = _fresh("owner");
        router = _fresh("router");
        harness = new MyFlashLoanReceiver(address(PROVIDER), ASSET, owner);
        vm.prank(owner);
        harness.setRouterAllowed(router, true);
        DEBT_TOKEN = POOL.getReserveData(ASSET).variableDebtTokenAddress;
        handler = new MyFlashLoanReceiverHandler(harness, POOL, ASSET, owner, AMOUNT, router);
        targetContract(address(handler));
        // One fixed sender: a random sender per call would touch a fresh account (and an
        // RPC round trip) on every step, for no extra coverage.
        targetSender(_fresh("invariantSender"));
        bytes4[] memory selectors = new bytes4[](2);
        selectors[0] = handler.operatorLoan.selector;
        selectors[1] = handler.attackerLoan.selector;
        targetSelector(FuzzSelector({addr: address(handler), selectors: selectors}));
    }

    /// @dev A plain account for this suite. Common labels ("alice", "owner") have public keys
    /// @dev and carry EIP-7702 delegation code on mainnet that swallows ETH sent to them, so
    /// @dev the label is prefixed and any code at the address is cleared.
    function _fresh(string memory label) internal returns (address a) {
        a = makeAddr(string(abi.encodePacked("harness/MyFlashLoanReceiver/", label)));
        if (a.code.length != 0) vm.etch(a, "");
    }

    /// @dev A valid, benign FlashParams. Attack tests deviate from this deliberately.
    function _defaultFlashParams() internal view returns (MyFlashLoanReceiver.FlashParams memory) {
        return MyFlashLoanReceiver.FlashParams({
            minAmountOut: 1,
            deadline: type(uint256).max,
            router: router
        });
    }

    function _defaultParams() internal view returns (bytes memory) {
        return abi.encode(_defaultFlashParams());
    }

    // ------------------------------------------------------------------ fuzz

    /// @notice Whatever the strategy does with the funds, a loan initiated by the operator
    /// @notice either reverts or costs the receiver at most the premium. This is the
    /// @notice property to keep when _executeStrategy() is filled in.
    function testFuzz_LoanCostsAtMostThePremium(uint256 amount) public {
        amount = bound(amount, ONE / 10, 200 * AMOUNT);
        // Aave rounds the premium half-up (PercentageMath); fund it rounded up.
        uint256 premium = (amount * POOL.FLASHLOAN_PREMIUM_TOTAL() + 9_999) / 10_000;
        deal(ASSET, address(harness), premium);
        uint256 before = IERC20(ASSET).balanceOf(address(harness));
        vm.prank(owner);
        harness.initiateFlashLoan(amount, _defaultFlashParams());
        uint256 after_ = IERC20(ASSET).balanceOf(address(harness));
        assertLe(before - after_, premium, "the loan cost more than the premium");
    }

    /// @notice No caller other than the receiver itself can drive the callback, for any
    /// @notice amount and any caller.
    function testFuzz_ThirdPartyCannotInitiate(uint256 callerSeed, uint256 amount) public {
        // A small pool of callers rather than a random address per run: each fresh address
        // costs an RPC round trip on a fork and adds nothing the gate can distinguish.
        address caller = _fresh(string(abi.encodePacked("caller", vm.toString(bound(callerSeed, 0, 3)))));
        amount = bound(amount, 1, 200 * AMOUNT);
        vm.prank(caller);
        vm.expectRevert(abi.encodeWithSignature("NotSelfInitiated(address)", caller));
        POOL.flashLoanSimple(address(harness), ASSET, amount, _defaultParams(), 0);
    }

    /// @notice Idle funds of any size survive a third-party loan of any size.
    function testFuzz_IdleFundsSurviveThirdPartyLoans(uint256 idle, uint256 amount) public {
        idle = bound(idle, 0, 1_000 * AMOUNT);
        amount = bound(amount, 1, 200 * AMOUNT);
        deal(ASSET, address(harness), idle);
        address attacker = _fresh("attacker");
        vm.prank(attacker);
        vm.expectRevert();
        POOL.flashLoanSimple(address(harness), ASSET, amount, _defaultParams(), 0);
        assertEq(IERC20(ASSET).balanceOf(address(harness)), idle, "idle funds were consumed");
    }

    // ------------------------------------------------------------- invariants

    /// @notice The receiver never ends up with a debt position on Aave, after any mix of
    /// @notice operator loans and attacker attempts.
    function invariant_NoDebtEverOpened() public view {
        assertEq(IERC20(DEBT_TOKEN).balanceOf(address(harness)), 0, "the receiver carries Aave debt");
    }

    /// @notice Every attacker attempt was refused.
    function invariant_AttacksAlwaysRevert() public view {
        // ghostAttacks only counts reverted attempts; a success reverts the handler itself.
        assertGe(handler.ghostAttacks(), 0);
    }
}

